package cn.blockforge.generated.generatedmod.alchemy;

import cn.blockforge.generated.generatedmod.*;
import cn.blockforge.generated.generatedmod.alchemy.batch.*;
import cn.blockforge.generated.generatedmod.alchemy.effects.*;
import cn.blockforge.generated.generatedmod.alchemy.inputs.*;
import cn.blockforge.generated.generatedmod.alchemy.research.*;
import cn.blockforge.generated.generatedmod.alchemy.simulation.*;
import cn.blockforge.generated.generatedmod.fire.*;
import cn.blockforge.generated.generatedmod.plants.*;
import cn.blockforge.generated.generatedmod.registry.ModRecipes;
import com.google.gson.*;
import net.minecraft.core.*;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.item.*;
import java.util.*;
import static cn.blockforge.generated.generatedmod.alchemy.simulation.AlchemySimulation.*;

/** Administrator-only catalog audit. No inventory writes, grants, experiments or certification. */
public final class AlchemyCoverage {
    private static JsonObject object(String key,String value){var n=new JsonObject();n.addProperty(key,value);return n;}
    private static Snapshot run(V5Batch.Profile profile,Map<String,Long> stocks,Map<String,Long> environment,long heatPerStep,boolean clarify){var rules=profile.rules();var s=AlchemySimulation.begin(rules,"catalog-audit",stocks,0,rules.weight(stocks,true),120012,environment);for(int phase=0;phase<6;phase++)for(int tick=0;tick<profile.phases()[phase];tick++){if(s.status()!=Status.ACTIVE)return s;var events=new ArrayList<Operation>();long sequence=s.lastSequence()+1;if(s.phase().ordinal()<phase)events.add(new Operation(sequence++,s.tick(),Action.ADVANCE,"",0));if(phase<(clarify?2:5)&&heatPerStep>0)events.add(new Operation(sequence++,s.tick(),Action.HEAT,"",heatPerStep));if(phase==5&&tick==profile.phases()[phase]-1)events.add(new Operation(sequence,s.tick(),Action.FINISH,"",0));s=AlchemySimulation.step(rules,s,events).snapshot();}return s;}
    public static JsonObject report(ServerPlayer p,boolean balance){
        long began=System.nanoTime();var root=new JsonObject();root.addProperty("schema",1);root.addProperty("kind","registered-catalog-and-reference-simulation");var defs=InputDefinitions.current();var policy=new AbilityCompiler.Policy(PillSnapshot.current(p.serverLevel()));var curriculum=ResearchCurriculum.load(p);root.addProperty("inputHash",defs.hash);root.addProperty("policyHash",policy.hash);var errors=new JsonArray();var herbs=new JsonArray();
        for(var herb:SpiritPlantCatalog.ALL){var row=object("id","wuxingxiantu:"+herb.id);var item=BuiltInRegistries.ITEM.get(net.minecraft.resources.ResourceLocation.parse("wuxingxiantu:"+herb.id));if(item==Items.AIR){errors.add("Unregistered herb: "+herb.id);continue;}var samples=new JsonArray();for(int age:new int[]{0,100,1500,6500,HerbAge.MAX})for(boolean prepared:List.of(false,true)){var stack=new ItemStack(item);HerbAge.setYears(stack,age);if(prepared)stack=HerbPreparation.prepare(stack);var material=AlchemyInputs.material(stack,defs);if(material.referenceMass()!=defs.massPerItem)errors.add("Material mass: "+herb.id);var sample=new JsonObject();sample.addProperty("years",age);sample.addProperty("prepared",prepared);sample.add("stocks",new Gson().toJsonTree(material.stocks()));samples.add(sample);}row.add("samples",samples);herbs.add(row);}root.add("herbs",herbs);
        var nonHerbal=new JsonArray();for(String id:new TreeSet<>(defs.nonHerbalIds())){var item=BuiltInRegistries.ITEM.get(net.minecraft.resources.ResourceLocation.parse(id));if(item==Items.AIR){errors.add("Unregistered non-herbal material: "+id);continue;}var material=AlchemyInputs.material(new ItemStack(item),defs);var row=object("id",id);row.add("stocks",new Gson().toJsonTree(material.stocks()));nonHerbal.add(row);}root.add("nonHerbal",nonHerbal);
        var fires=new JsonArray();for(var fire:FireCatalog.ALL){var row=object("id",fire.key().toString());row.addProperty("rate",defs.fireMaximumRate(fire.key().toString()));row.addProperty("tier",fire.tier());fires.add(row);}root.add("fires",fires);
        var profiles=new ArrayList<V5Batch.Profile>();var devices=new JsonArray();for(int tier=0;tier<6;tier++){var items=NonNullList.withSize(AlchemyFurnaceBlockEntity.CONTAINER_SIZE,ItemStack.EMPTY);var herb=new ItemStack(SpiritPlantRegistry.SPIRIT_SPROUT_GRASS_ITEM.get(),4);HerbAge.setYears(herb,1500);items.set(0,herb);items.set(8,FireBottleData.fresh(1));var doc=V5Batch.prepare(p.serverLevel(),p.blockPosition(),p,tier,0,AlchemyBalance.fuelCapacity(tier),items,new int[]{4,0,0,0,0,0,0,0},"ordinary_free","");var profile=V5Batch.profile(doc.getString("Profile"),doc.getInt("Burn"));profiles.add(profile);var row=new JsonObject();row.addProperty("tier",tier);row.addProperty("capacity",AlchemyBalance.fuelCapacity(tier));row.addProperty("prepaid",profile.requiredFuel());row.addProperty("heatCapacity",profile.rules().limits.heatCapacity());row.addProperty("pressureLimit",profile.rules().limits.burstPressure());devices.add(row);}root.add("devices",devices);
        var recipes=new JsonArray();var formulaIds=new TreeSet<String>();for(var recipe:p.server.getRecipeManager().getAllRecipesFor(ModRecipes.ALCHEMY_TYPE.get()).stream().sorted(Comparator.comparing(r->r.getId().toString())).toList()){var row=object("id",recipe.getId().toString());row.addProperty("formula",recipe.formulaId().toString());formulaIds.add(recipe.formulaId().toString());var ingredients=new JsonArray();for(var term:recipe.getIngredients()){var choices=term.getItems();if(choices.length==0)errors.add("Empty ingredient: "+recipe.getId());for(var choice:choices)try{AlchemyInputs.material(choice.copyWithCount(1),defs);ingredients.add(BuiltInRegistries.ITEM.getKey(choice.getItem()).toString());}catch(RuntimeException invalid){errors.add(recipe.getId()+": "+invalid.getMessage());}}row.add("ingredients",ingredients);recipes.add(row);}root.add("recipes",recipes);
        var templates=new JsonArray();var covered=new HashSet<String>();for(var template:curriculum.templates){var row=object("id",template.id());row.addProperty("formula",template.formula());row.addProperty("module",template.module());covered.add(template.formula());templates.add(row);}for(var type:PillCatalog.values())if(!covered.contains("wuxingxiantu:"+type.id)||!formulaIds.contains("wuxingxiantu:"+type.id))errors.add("Uncovered pill: "+type.id);root.add("templates",templates);
        var imports=new JsonArray();for(var pill:PillCatalog.values())for(var quality:PillData.Grade.values())for(int rank=1;rank<=5;rank++)for(var element:pill==PillCatalog.ROOT?PillData.Element.values():new PillData.Element[]{PillData.Element.METAL})for(int cultivation=0;cultivation<(pill==PillCatalog.CULTIVATION?9:1);cultivation++){var old=MedicineTier.set(PillData.create(pill,quality,element,cultivation),rank);var result=PillSnapshot.read(LegacyPillImport.plan(old).result());var row=object("pill",pill.id);row.addProperty("sourceQuality",quality.name());row.addProperty("sourceRank",rank);row.addProperty("sourceElement",element.name());row.addProperty("sourceCultivationRealm",cultivation);row.addProperty("grade",result.grade());row.add("effects",new Gson().toJsonTree(result.effects()));imports.add(row);}root.add("importMappings",imports);
        if(balance){var simulations=new JsonArray();var times=new ArrayList<Long>();for(var herb:SpiritPlantCatalog.ALL)for(int years:new int[]{0,1500,HerbAge.MAX})for(int count:new int[]{1,4,64})for(boolean prepared:List.of(false,true))for(int tier=0;tier<6;tier++)for(int fire:new int[]{1,9})for(boolean clarify:List.of(false,true)){var item=new ItemStack(BuiltInRegistries.ITEM.get(net.minecraft.resources.ResourceLocation.parse("wuxingxiantu:"+herb.id)),count);HerbAge.setYears(item,years);if(prepared)item.getOrCreateTag().putBoolean(HerbPreparation.KEY,true);var material=AlchemyInputs.material(item,defs);var profile=profiles.get(tier);var env=new HashMap<>(AlchemyEnvironment.sample(p.serverLevel(),p.blockPosition()).values());env.put("fire_tier",(long)fire);long start=System.nanoTime();var terminal=run(profile,material.stocks(),env,Math.min((long)profile.burn()*10,defs.fireMaximumRate(FireCatalog.tier(fire).key().toString())),clarify);var result=AbilityCompiler.compile(policy,profile.rules(),terminal,0);times.add(System.nanoTime()-start);var row=object("herb",herb.id);row.addProperty("years",years);row.addProperty("count",count);row.addProperty("prepared",prepared);row.addProperty("device",tier);row.addProperty("fire",fire);row.addProperty("heatOffAfterExtraction",clarify);row.addProperty("terminal",terminal.status().name());row.addProperty("grade",result.grade());row.addProperty("quantity",result.quantity());row.addProperty("toxicity",result.toxicity());row.addProperty("massConserved",terminal.ledger().initialMass()==profile.rules().weight(terminal.stocks(),true)+terminal.ledger().ashMass()+terminal.ledger().residualMass()+terminal.ledger().ventedMass());simulations.add(row);}Collections.sort(times);root.add("referenceSimulations",simulations);root.addProperty("referenceP50Micros",times.get(times.size()/2)/1000);root.addProperty("referenceP95Micros",times.get(times.size()*95/100)/1000);root.addProperty("referenceP99Micros",times.get(times.size()*99/100)/1000);}
        root.add("errors",errors);root.addProperty("passed",errors.isEmpty());root.addProperty("herbCount",herbs.size());root.addProperty("nonHerbalCount",nonHerbal.size());root.addProperty("recipeCount",recipes.size());root.addProperty("pillCount",PillCatalog.values().length);root.addProperty("templateCount",templates.size());root.addProperty("reactionCount",profiles.get(0).rules().reactions.size());root.addProperty("moduleCount",policy.modules.size());root.addProperty("elapsedMillis",(System.nanoTime()-began)/1000000);return root;
    }
    public static java.nio.file.Path write(ServerPlayer p,boolean balance){var report=report(p,balance);var path=p.server.getWorldPath(net.minecraft.world.level.storage.LevelResource.ROOT).resolve("data/alchemy-v5/reports/catalog-12.json");try{java.nio.file.Files.createDirectories(path.getParent());java.nio.file.Files.writeString(path,new GsonBuilder().setPrettyPrinting().create().toJson(report),java.nio.charset.StandardCharsets.UTF_8);}catch(java.io.IOException error){throw new IllegalStateException("Cannot write catalog audit",error);}return path;}
    private AlchemyCoverage(){}
}
